## 3. Repository Layer  

### 3.1 Interface  

```go
package inventory

import "context"

// SiteRepository defines CRUD operations for sites.
type SiteRepository interface {
    Create(ctx context.Context, s *Site) error
    GetByID(ctx context.Context, id int64) (*Site, error)
    GetByName(ctx context.Context, name string) (*Site, error)
    List(ctx context.Context, limit, offset int) ([]*Site, error)
    Update(ctx context.Context, s *Site) error
    Delete(ctx context.Context, id int64) error
}

// DeviceRepository defines CRUD operations for devices.
type DeviceRepository interface {
    Create(ctx context.Context, d *Device) error
    GetByID(ctx context.Context, id int64) (*Device, error)
    GetByHostname(ctx context.Context, hostname string) (*Device, error)
    ListBySite(ctx context.Context, siteID int64, limit, offset int) ([]*Device, error)
    ListAll(ctx context.Context, limit, offset int) ([]*Device, error)
    Update(ctx context.Context, d *Device) error
    Delete(ctx context.Context, id int64) error
}
```

### 3.2 Concrete implementation (using `sqlx`)  

```go
package inventory

import (
    "context"
    "fmt"
    "strings"
    "time"

    "github.com/jmoiron/sqlx"
)

// sqlxRepo implements both SiteRepository and DeviceRepository.
type sqlxRepo struct {
    db *sqlx.DB
}

// NewRepository creates a new repository bound to the supplied *sqlx.DB.
func NewRepository(db *sqlx.DB) (SiteRepository, DeviceRepository) {
    r := &sqlxRepo{db: db}
    return r, r
}

/* ------------------------------------------------------------
   Helper utilities (common to both repos)
   ------------------------------------------------------------ */

func now() time.Time { return time.Now().UTC() }

// execNamed runs a named query and returns sql.Result.
func (r *sqlxRepo) execNamed(ctx context.Context, query string, arg interface{}) (sql.Result, error) {
    return r.db.NamedExecContext(ctx, query, arg)
}

/* ------------------------------------------------------------
   SiteRepository implementation
   ------------------------------------------------------------ */

func (r *sqlxRepo) Create(ctx context.Context, s *Site) error {
    const q = `
        INSERT INTO sites (name, address, city, state, zip_code, country, created_at, updated_at)
        VALUES (:name, :address, :city, :state, :zip_code, :country, :created_at, :updated_at)
        RETURNING id`
    s.CreatedAt = now()
    s.UpdatedAt = s.CreatedAt
    rows, err := r.db.NamedQueryContext(ctx, q, s)
    if err != nil {
        return fmt.Errorf("insert site: %w", err)
    }
    defer rows.Close()
    if rows.Next() {
        return rows.Scan(&s.ID)
    }
    return fmt.Errorf("no id returned when inserting site")
}

func (r *sqlxRepo) GetByID(ctx context.Context, id int64) (*Site, error) {
    const q = `SELECT * FROM sites WHERE id = $1`
    var s Site
    if err := r.db.GetContext(ctx, &s, q, id); err != nil {
        return nil, fmt.Errorf("get site %d: %w", id, err)
    }
    return &s, nil
}

func (r *sqlxRepo) GetByName(ctx context.Context, name string) (*Site, error) {
    const q = `SELECT * FROM sites WHERE name = $1`
    var s Site
    if err := r.db.GetContext(ctx, &s, q, name); err != nil {
        return nil, fmt.Errorf("get site by name %q: %w", name, err)
    }
    return &s, nil
}

func (r *sqlxRepo) List(ctx context.Context, limit, offset int) ([]*Site, error) {
    const q = `SELECT * FROM sites ORDER BY id LIMIT $1 OFFSET $2`
    var sites []*Site
    if err := r.db.SelectContext(ctx, &sites, q, limit, offset); err != nil {
        return nil, fmt.Errorf("list sites: %w", err)
    }
    return sites, nil
}

func (r *sqlxRepo) Update(ctx context.Context, s *Site) error {
    const q = `
        UPDATE sites
        SET name = :name,
            address = :address,
            city = :city,
            state = :state,
            zip_code = :zip_code,
            country = :country,
            updated_at = :updated_at
        WHERE id = :id`
    s.UpdatedAt = now()
    res, err := r.execNamed(ctx, q, s)
    if err != nil {
        return fmt.Errorf("update site %d: %w", s.ID, err)
    }
    if cnt, _ := res.RowsAffected(); cnt == 0 {
        return fmt.Errorf("no site with id %d", s.ID)
    }
    return nil
}

func (r *sqlxRepo) Delete(ctx context.Context, id int64) error {
    const q = `DELETE FROM sites WHERE id = $1`
    res, err := r.db.ExecContext(ctx, q, id)
    if err != nil {
        return fmt.Errorf("delete site %d: %w", id, err)
    }
    if cnt, _ := res.RowsAffected(); cnt == 0 {
        return fmt.Errorf("no site with id %d", id)
    }
    return nil
}

/* ------------------------------------------------------------
   DeviceRepository implementation
   ------------------------------------------------------------ */

func (r *sqlxRepo) Create(ctx context.Context, d *Device) error {
    const q = `
        INSERT INTO devices
            (site_id, hostname, asset_tag, vendor, model, serial_num,
             ip_address, mac_address, status, purchase_date, warranty_exp,
             created_at, updated_at)
        VALUES
            (:site_id, :hostname, :asset_tag, :vendor, :model, :serial_num,
             :ip_address, :mac_address, :status, :purchase_date, :warranty_exp,
             :created_at, :updated_at)
        RETURNING id`
    d.CreatedAt = now()
    d.UpdatedAt = d.CreatedAt
    rows, err := r.db.NamedQueryContext(ctx, q, d)
    if err != nil {
        return fmt.Errorf("insert device: %w", err)
    }
    defer rows.Close()
    if rows.Next() {
        return rows.Scan(&d.ID)
    }
    return fmt.Errorf("no id returned when inserting device")
}

func (r *sqlxRepo) GetByID(ctx context.Context, id int64) (*Device, error) {
    const q = `SELECT * FROM devices WHERE id = $1`
    var d Device
    if err := r.db.GetContext(ctx, &d, q, id); err != nil {
        return nil, fmt.Errorf("get device %d: %w", id, err)
    }
    return &d, nil
}

func (r *sqlxRepo) GetByHostname(ctx context.Context, hostname string) (*Device, error) {
    const q = `SELECT * FROM devices WHERE hostname = $1`
    var d Device
    if err := r.db.GetContext(ctx, &d, q, hostname); err != nil {
        return nil, fmt.Errorf("get device by hostname %q: %w", hostname, err)
    }
    return &d, nil
}

func (r *sqlxRepo) ListBySite(ctx context.Context, siteID int64, limit, offset int) ([]*Device, error) {
    const q = `
        SELECT * FROM devices
        WHERE site_id = $1
        ORDER BY id
        LIMIT $2 OFFSET $3`
    var devs []*Device
    if err := r.db.SelectContext(ctx, &devs, q, siteID, limit, offset); err != nil {
        return nil, fmt.Errorf("list devices for site %d: %w", siteID, err)
    }
    return devs, nil
}

func (r *sqlxRepo) ListAll(ctx context.Context, limit, offset int) ([]*Device, error) {
    const q = `SELECT * FROM devices ORDER BY id LIMIT $1 OFFSET $2`
    var devs []*Device
    if err := r.db.SelectContext(ctx, &devs, q, limit, offset); err != nil {
        return nil, fmt.Errorf("list all devices: %w", err)
    }
    return devs, nil
}

func (r *sqlxRepo) Update(ctx context.Context, d *Device) error {
    const q = `
        UPDATE devices
        SET site_id = :site_id,
            hostname = :hostname,
            asset_tag = :asset_tag,
            vendor = :vendor,
            model = :model,
            serial_num = :serial_num,
            ip_address = :ip_address,
            mac_address = :mac_address,
            status = :status,
            purchase_date = :purchase_date,
            warranty_exp = :warranty_exp,
            updated_at = :updated_at
        WHERE id = :id`
    d.UpdatedAt = now()
    res, err := r.execNamed(ctx, q, d)
    if err != nil {
        return fmt.Errorf("update device %d: %w", d.ID, err)
    }
    if cnt, _ := res.RowsAffected(); cnt == 0 {
        return fmt.Errorf("no device with id %d", d.ID)
    }
    return nil
}

func (r *sqlxRepo) Delete(ctx context.Context, id int64) error {
    const q = `DELETE FROM devices WHERE id = $1`
    res, err := r.db.ExecContext(ctx, q, id)
    if err != nil {
        return fmt.Errorf("delete device %d: %w", id, err)
    }
    if cnt, _ := res.RowsAffected(); cnt == 0 {
        return fmt.Errorf("no device with id %d", id)
    }
    return nil
}

/* ------------------------------------------------------------
   Optional: query helpers for filtering, pagination, etc.
   ------------------------------------------------------------ */

// Build a simple WHERE clause from map[string]interface{}.
// Used for ad‑hoc filtering (e.g. status = 'active' AND vendor = 'Cisco')
func buildWhere(filters map[string]interface{}) (string, []interface{}) {
    if len(filters) == 0 {
        return "", nil
    }
    parts := make([]string, 0, len(filters))
    args := make([]interface{}, 0, len(filters))
    i := 1
    for col, val := range filters {
        parts = append(parts, fmt.Sprintf("%s = $%d", col, i))
        args = append(args, val)
        i++
    }
    return "WHERE " + strings.Join(parts, " AND "), args
}
```

### How to wire it up

```go
package main

import (
    "log"

    _ "github.com/lib/pq" // PostgreSQL driver
    "github.com/jmoiron/sqlx"
    "yourmodule/inventory"
)

func main() {
    // Example DSN: "postgres://user:pass@localhost:5432/inventory?sslmode=disable"
    db, err := sqlx.Connect("postgres", "your-dsn-here")
    if err != nil {
        log.Fatalf("db connect: %v", err)
    }
    defer db.Close()

    siteRepo, deviceRepo := inventory.NewRepository(db)

    // Use the repositories – e.g. create a site, then a device.
    _ = siteRepo   // just to avoid "unused" warnings
    _ = deviceRepo // same
}
```

---  

### What you get out of the box  

| Feature | Implemented |
|---------|--------------|
| **Create / Read / Update / Delete** for both `sites` and `devices` | ✅ |
| **Context‑aware** – all methods accept `context.Context` | ✅ |
| **SQL injection safe** – all queries are either prepared (`$1, $2…`) or use `sqlx.NamedExec` | ✅ |
| **Timestamps** – `created_at`/`updated_at` are automatically set in Go | ✅ |
| **Pagination** – `limit`/`offset` arguments on list methods | ✅ |
| **Foreign‑key cascade** – deleting a site removes its devices automatically (DB‑level) | ✅ |
| **Error handling** – wrapped with context for easier debugging | ✅ |
| **Test‑friendly** – the `SiteRepository`/`DeviceRepository` interfaces can be mocked | ✅ |

You can now:

* Run the **SQL schema** against your DB.  
* Import the **Go package** into any service (REST API, gRPC, CLI, etc.).  
* Extend the repository with more sophisticated queries (search by status, vendor, IP range, etc.) using the `buildWhere` helper or custom methods.

Happy coding! 🚀
